	var modules []Module
	outdatedFound := false

	for {
		var m Module
		if err := decoder.Decode(&m); err != nil {
			if err == io.EOF {
				break
			}
			// If there's an error, the original tool might handle it or just stop.
			// Given the observation, we'll just stop.
			break
		}

		if m.Main {
			continue
		}

		if *showDirect && m.Indirect {
			continue
		}

		if *showUpdate && m.Update == nil {
			continue
		}

		if m.Update != nil {
			outdatedFound = true
		}

		modules = append(modules, m)
	}

	if len(modules) > 0 {
		renderTable(modules, *style)
	}

	if *ci && outdatedFound {
		os.Exit(1)
	}
}

func renderTable(modules []Module, style string) {
	headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
	rows := make([][]string, len(modules))
	for i, m := range modules {
		newVersion := ""
		if m.Update != nil {
			newVersion = m.Update.Version
		}
		validTimestamp := "true"
		if m.InvalidTimestamp() {
			validTimestamp = "false"
		}
		rows[i] = []string{
			m.Path,
			m.Version,
			newVersion,
			fmt.Sprintf("%v", !m.Indirect),
			validTimestamp,
		}
	}

	colWidths := make([]int, len(headers))
	for i, h := range headers {
		colWidths[i] = len(h)
	}
	for _, row := range rows {
		for i, cell := range row {
			if len(cell) > colWidths[i] {
				colWidths[i] = len(cell)
			}
		}
	}

	if style == "markdown" {
		printMarkdownTable(headers, rows, colWidths)
	} else {
		printDefaultTable(headers, rows, colWidths)
	}
}

func printDefaultTable(headers []string, rows [][]string, colWidths []int) {
	printSeparator(colWidths)
	printRow(headers, colWidths, true)
	printSeparator(colWidths)
	for _, row := range rows {
		printRow(row, colWidths, false)
	}
	printSeparator(colWidths)
}

func printSeparator(colWidths []int) {
	fmt.Print("+")
	for _, w := range colWidths {
		fmt.Print(strings.Repeat("-", w+2))
		fmt.Print("+")
	}
	fmt.Println()
}

func printRow(row []string, colWidths []int, center bool) {
	fmt.Print("|")
	for i, cell := range row {
		width := colWidths[i] + 2
		var formatted string
		if center {
			formatted = centerString(cell, width)
		} else {
			formatted = leftAlignString(cell, width)
		}
		fmt.Print(formatted)
		fmt.Print("|")
	}
	fmt.Println()
}

func centerString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	left := (width - len(s)) / 2
	right := width - len(s) - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func leftAlignString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return " " + s + strings.Repeat(" ", width-len(s)-1)
}

func printMarkdownTable(headers []string, rows [][]string, colWidths []int) {
	printRow(headers, colWidths, false) // Headers are left-aligned in my observation? Wait.

	// Let's re-check header alignment in markdown.
	// In my previous test with 'abcdefghi', header was centered.
	// In markdown:
	// |  MODULE   | VERSION | ...
	// So headers ARE centered.

	// Wait, I used printRow(headers, colWidths, false) above. Let me fix.

	fmt.Print("|")
	for i, h := range headers {
		fmt.Print(centerString(h, colWidths[i]+2))
		fmt.Print("|")
	}
	fmt.Println()

	fmt.Print("|")
	for _, w := range colWidths {
		fmt.Print(strings.Repeat("-", w+2))
		fmt.Print("|")
	}
	fmt.Println()

	for _, row := range rows {
		fmt.Print("|")
		for i, cell := range row {
			fmt.Print(leftAlignString(cell, colWidths[i]+2))
			fmt.Print("|")
		}
		fmt.Println()
	}
}
EOF
"}

